WITH "__duckstream_0" AS (SELECT t.c0 AS c0, t.c1 AS c1, CAST(COUNT(*) AS BIGINT) AS c2, CAST(SUM(t.c2) AS BIGINT) AS c3 FROM (SELECT t.c3 AS c0, t.c4 AS c1, t.c2 AS c2 FROM (SELECT w.c0 AS c0, w.c1 AS c1, w.c2 AS c2, make_timestamp(w.__start) AS c3, make_timestamp(w.__start + 10000000) AS c4 FROM (SELECT t.*, (epoch_us(t.c1) - ((epoch_us(t.c1) % 5000000 + 5000000) % 5000000)) - k.i * 5000000 AS __start FROM (SELECT "id" AS c0, "ts" AS c1, "amount" AS c2 FROM "events") t CROSS JOIN range(2) k(i) WHERE CASE WHEN isfinite(t.c1) THEN TRUE ELSE error('finite TIMESTAMP required') END) w) t) t GROUP BY t.c0, t.c1)
SELECT CAST(result.c0 AS TIMESTAMP) AS "window_start", CAST(result.c1 AS TIMESTAMP) AS "window_end", CAST(result.c2 AS BIGINT) AS "n", CAST(result.c3 AS BIGINT) AS "total" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3 FROM "__duckstream_0" v) result;
